<script setup lang="ts">
import LearningPage from './pages/LearningPage.vue';
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';import {open,save,ask} from '@tauri-apps/plugin-dialog';import {getCurrentWindow} from '@tauri-apps/api/window';import {api,type Workspace,type Schema} from './api';import {useLab} from './store';import HelpPage from './pages/HelpPage.vue';import ConnectionDialog from './components/ConnectionDialog.vue';
import IdePage from './pages/IdePage.vue';import AlgebraPage from './pages/AlgebraPage.vue';import TransactionPage from './pages/TransactionPage.vue';import ExercisePage from './pages/ExercisePage.vue';import CasePage from './pages/CasePage.vue';
const lab=useLab();const fixtureSelection=ref('student');watch(()=>[lab.workspace?.fixture,lab.engine],()=>{fixtureSelection.value=lab.workspace?.fixture??'student'},{immediate:true});const connection=ref(false);const logs=ref(false);const pending=ref<(()=>Promise<void>)>();const themeMedia=matchMedia('(prefers-color-scheme: dark)');const systemDark=ref(themeMedia.matches);function updateSystemTheme(event:MediaQueryListEvent){systemDark.value=event.matches}const resolvedTheme=computed(()=>lab.theme==='system'?(systemDark.value?'dark':'light'):lab.theme);const nav=[['learn','⌂','课程学习'],['cases','◇','案件挑战'],['ide','▤','自由实验'],['help','?','使用指南']];let timer:ReturnType<typeof setInterval>|undefined;let unlisten:(()=>void)|undefined;let closing=false;
watch(resolvedTheme,t=>document.documentElement.dataset.theme=t,{immediate:true});
async function saveProject(as=false){try{const migrated=lab.projectPath!==''&&lab.workspace?.view&&typeof lab.workspace.view==='object'&&!Array.isArray(lab.workspace.view)&&lab.workspace.view.migrated_from===1;let path=as||migrated?'':lab.projectPath;if(!path)path=await save({defaultPath:'数据库学习.sqlkproj',filters:[{name:'SQL-Killer 工程',extensions:['sqlkproj']}]})??'';if(!path)return false;const rev=lab.revision;await api('save_project',{path,workspace:lab.snapshot()});lab.projectPath=path;const view=lab.workspace?.view;if(view&&typeof view==='object'&&!Array.isArray(view))delete view.migrated_from;if(rev===lab.revision)lab.dirty=false;lab.log('工程已保存');return true;}catch(e){lab.fail(e);return false}}
async function guard(action:()=>Promise<void>){if(lab.dirty)pending.value=action;else await action()}
async function openProject(){const path=await open({multiple:false,filters:[{name:'SQL-Killer 工程',extensions:['sqlkproj']}]});if(typeof path==='string'){const r=await api<{workspace:Workspace,schema:Schema}>('load_project',{path});lab.restore(r.workspace,r.schema);lab.projectPath=path;lab.log('工程已恢复')}}
async function newProject(){const w=await api<Workspace>('new_project');lab.restore(w);lab.projectPath='';await lab.refresh();}
async function recover(){try{const r=await api<{workspace:Workspace,schema:Schema}>('recover');lab.restore(r.workspace,r.schema);lab.dirty=true;lab.recovery=false;lab.log('已恢复自动保存副本，请另存工程');}catch(e){lab.fail(e)}}
async function reset(){if(!await ask('恢复所选示例数据库将替换当前沙箱数据。SQL 文档和学习记录会保留。',{title:'重置教学沙箱',kind:'warning'}))return;const fixture=fixtureSelection.value;try{if(lab.engine==='mysql'){await api('mysql_reset',{fixture,session:'main'});await lab.refresh()}else{lab.schema=await api<Schema>('reset',{fixture});lab.workspace!.fixture=fixture;}lab.touch();lab.log('示例数据库已恢复')}catch(e){lab.fail(e)}}
async function importSql(){const path=await open({filters:[{name:'SQL',extensions:['sql','txt']}]});if(typeof path==='string'){const text=await api<string>('read_sql',{path});const id=crypto.randomUUID();lab.workspace!.documents.push({id,title:path.split(/[\\/]/).pop()??'导入.sql',text});lab.workspace!.active_document=id;lab.page='ide';lab.touch();}}
async function choice(saveFirst:boolean){const action=pending.value;if(saveFirst&&!await saveProject())return;pending.value=undefined;if(action)await action().catch(lab.fail)}
function hotkeys(e:KeyboardEvent){if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();void saveProject(e.shiftKey)}if(e.ctrlKey&&e.key.toLowerCase()==='o'){e.preventDefault();void guard(openProject).catch(lab.fail)}}
onMounted(async()=>{themeMedia.addEventListener('change',updateSystemTheme);await lab.bootstrap();timer=setInterval(()=>{if(lab.workspace&&lab.dirty&&!Object.keys(lab.jobs).length)void api('autosave',{workspace:lab.snapshot()}).catch(lab.fail)},30000);window.addEventListener('keydown',hotkeys);try{unlisten=await getCurrentWindow().onCloseRequested(async e=>{if(closing)return;e.preventDefault();await guard(async()=>{await lab.cancel();closing=true;await getCurrentWindow().destroy()})});}catch{/* browser unit preview has no native window */}});
onBeforeUnmount(()=>{themeMedia.removeEventListener('change',updateSystemTheme);clearInterval(timer);unlisten?.();window.removeEventListener('keydown',hotkeys)});
</script>
<template><div class="application"><header class="app-header"><div class="brand"><div class="brand-mark">S<span>›</span></div><div><b>SQL-Killer</b><small>数据库学习实验室</small></div><span class="version">{{lab.version}}</span></div><div class="header-actions"><template v-if="['ide','algebra','transactions'].includes(lab.page)"><select v-if="lab.workspace" v-model="fixtureSelection" aria-label="示例数据库" title="选择后点击重置加载"><option value="student">HNU Student</option><option value="hotel">Hotel</option><option value="bank">Bank</option><option value="empty">Empty Sandbox</option></select><select v-model="lab.engine" aria-label="数据库引擎" @change="lab.invalidateJobs();lab.engine==='mysql'?(connection=true):lab.refresh()"><option value="sqlite">SQLite · 本地沙箱</option><option value="mysql">MySQL · 真实连接</option></select><button @click="connection=true" title="MySQL 连接设置">⚙ 连接</button><button @click="reset">↻ 重置</button></template><select v-model="lab.theme" aria-label="主题"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></div></header><div class="app-menu"><button @click="guard(newProject).catch(lab.fail)">新建工程</button><button @click="guard(openProject).catch(lab.fail)">打开工程</button><button @click="saveProject()">保存{{lab.dirty?' ●':''}}</button><button @click="saveProject(true)">另存为</button><button @click="importSql().catch(lab.fail)">导入 SQL</button><span class="project-path">{{lab.projectPath||'未命名学习工程'}}</span><button v-if="Object.keys(lab.jobs).length" class="warning" @click="lab.cancel()">取消后台任务（{{Object.keys(lab.jobs).length}}）</button></div><nav class="main-nav"><button v-for="[id,icon,label] in nav" :key="id" :class="{active:lab.page===id||(id==='learn'&&lab.page==='exercises')||(id==='ide'&&['algebra','transactions'].includes(lab.page))}" :data-page="id" @click="lab.page=id"><span>{{icon}}</span>{{label}}</button><div class="nav-tag">LEARN · EXPLORE · UNDERSTAND</div></nav><nav v-if="['ide','algebra','transactions'].includes(lab.page)" class="experiment-nav"><button v-for="[id,label] in [['ide','SQL 工作台'],['algebra','关系代数'],['transactions','事务实验']]" :key="id" :data-page="id==='ide'?'workbench':id" :class="{active:lab.page===id}" @click="lab.page=id">{{label}}</button></nav><div v-if="lab.error" class="error-banner" role="alert"><span>{{lab.error}}</span><button @click="lab.error=''" aria-label="关闭错误">×</button></div><div v-if="lab.recovery" class="recovery-banner">找到上次的自动保存副本。<button @click="recover">恢复学习工程</button><button @click="lab.recovery=false">暂不恢复</button></div><main v-if="lab.workspace" :key="lab.projectGeneration" class="app-main"><LearningPage v-if="lab.page==='learn'"/><CasePage v-else-if="lab.page==='cases'" :theme="resolvedTheme" @connect="connection=true"/><IdePage v-else-if="lab.page==='ide'" :theme="resolvedTheme"/><AlgebraPage v-else-if="lab.page==='algebra'" :theme="resolvedTheme"/><TransactionPage v-else-if="lab.page==='transactions'" :theme="resolvedTheme" @connect="connection=true"/><ExercisePage v-else-if="lab.page==='exercises'" :theme="resolvedTheme"/><HelpPage v-else/></main><div v-else class="empty large">正在初始化数据库学习环境…</div><section v-if="logs" class="log-panel"><p v-for="(line,i) in lab.logs" :key="i">{{line}}</p><p v-if="!lab.logs.length">暂无执行记录</p></section><footer class="status-bar"><button @click="logs=!logs">{{logs?'▾':'▴'}} Output</button><span class="online-dot"/><span class="status-text">{{lab.status}}</span><span>{{lab.schema.engine}}</span><span>UTF-8</span><span>离线教学</span></footer><ConnectionDialog v-if="connection" @close="connection=false"/><div v-if="pending" class="modal-backdrop"><section class="modal small" role="dialog" aria-label="未保存修改"><h2>保存当前学习工程？</h2><p>工程包含 SQL 文档、数据库数据和实验记录。</p><div class="toolbar"><button @click="pending=undefined">取消</button><button @click="choice(false)">不保存</button><button class="primary" @click="choice(true)">保存并继续</button></div></section></div></div></template>
